    "pl": {
      "name": "Pobudzony",
      "description": "Emocja ta odnosi się do stanu podwyższonej aktywności fizjologicznej. Obejmuje zwiększoną czujność, energię i wrażliwość sensoryczną. Pobudzenie może być wywołane przez różne bodźce, w tym ekscytację, strach lub oczekiwanie. Często wiąże się z przyspieszonym tętnem, szybkim oddychaniem i wyrzutem adrenaliny. Pobudzenie może być pozytywne (jak ekscytacja czy entuzjazm) lub negatywne (jak niepokój czy stres)."
    },
